"""Esquema del PostgreSQL del SOC y agregación incremental atómica."""

from auth_schema import AUTH_SCHEMA
from browsing_schema import install_browsing
from sqlite_schema import SCHEMA_SQL

# Se conserva el contrato de fechas ISO UTC del repositorio actual. Las series
# temporales nuevas usan timestamptz. No es un conversor SQL de propósito general.
BASE_SCHEMA = SCHEMA_SQL.replace(
    "INTEGER PRIMARY KEY AUTOINCREMENT", "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY"
)

METRICS_SCHEMA = """
CREATE TABLE IF NOT EXISTS soc_schema_version (
    singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
    version INTEGER NOT NULL
);
INSERT INTO soc_schema_version VALUES (1, 1) ON CONFLICT DO NOTHING;
CREATE INDEX IF NOT EXISTS idx_events_source_time
    ON normalized_events(source_name, event_time_utc);
CREATE INDEX IF NOT EXISTS idx_alerts_source_time
    ON alerts(source_name, generated_at_utc);
CREATE INDEX IF NOT EXISTS idx_alerts_rule_entity_time
    ON alerts(source_name, rule_id, user_key, client_ip_key, last_seen_local);
CREATE INDEX IF NOT EXISTS idx_alerts_status
    ON alerts(source_name, investigation_status, severity);

CREATE TABLE IF NOT EXISTS service_labels (
    relying_party TEXT PRIMARY KEY,
    display_name TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS service_minute_metrics (
    source_name TEXT NOT NULL,
    minute_utc TIMESTAMPTZ NOT NULL,
    relying_party TEXT NOT NULL,
    total_events BIGINT NOT NULL DEFAULT 0,
    success_count BIGINT NOT NULL DEFAULT 0,
    failure_count BIGINT NOT NULL DEFAULT 0,
    lockout_count BIGINT NOT NULL DEFAULT 0,
    other_count BIGINT NOT NULL DEFAULT 0,
    updated_at_utc TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY(source_name, minute_utc, relying_party)
);
CREATE INDEX IF NOT EXISTS idx_metrics_time ON service_minute_metrics(minute_utc);

CREATE OR REPLACE FUNCTION soc_aggregate_event() RETURNS TRIGGER
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.is_consistent <> 1 OR COALESCE(NEW.event_time_utc, '') = ''
       OR TRIM(COALESCE(NEW.relying_party, '')) = '' THEN
        RETURN NEW;
    END IF;
    INSERT INTO service_minute_metrics (
        source_name, minute_utc, relying_party, total_events,
        success_count, failure_count, lockout_count, other_count
    ) VALUES (
        NEW.source_name, date_trunc('minute', NEW.event_time_utc::timestamptz),
        NEW.relying_party, NEW.event_count,
        CASE WHEN NEW.event_class = 'success' THEN NEW.event_count ELSE 0 END,
        CASE WHEN NEW.event_class = 'failure' THEN NEW.event_count ELSE 0 END,
        CASE WHEN NEW.event_class = 'lockout' THEN NEW.event_count ELSE 0 END,
        CASE WHEN NEW.event_class NOT IN ('success', 'failure', 'lockout')
             THEN NEW.event_count ELSE 0 END
    )
    ON CONFLICT (source_name, minute_utc, relying_party) DO UPDATE SET
        total_events = service_minute_metrics.total_events + EXCLUDED.total_events,
        success_count = service_minute_metrics.success_count + EXCLUDED.success_count,
        failure_count = service_minute_metrics.failure_count + EXCLUDED.failure_count,
        lockout_count = service_minute_metrics.lockout_count + EXCLUDED.lockout_count,
        other_count = service_minute_metrics.other_count + EXCLUDED.other_count,
        updated_at_utc = CURRENT_TIMESTAMP;
    RETURN NEW;
END;
$$;
CREATE OR REPLACE TRIGGER soc_event_metrics AFTER INSERT ON normalized_events
FOR EACH ROW EXECUTE FUNCTION soc_aggregate_event();

CREATE OR REPLACE VIEW soc_service_minute_dashboard AS
SELECT m.source_name, m.minute_utc,
       COALESCE(l.display_name, 'Servicio ' || LEFT(md5(m.relying_party), 10)) AS service,
       m.total_events, m.success_count, m.failure_count, m.lockout_count, m.other_count,
       m.updated_at_utc
FROM service_minute_metrics m
LEFT JOIN service_labels l ON l.relying_party = m.relying_party;
"""


def install_schema(connection) -> None:
    with connection.transaction():
        connection.execute(BASE_SCHEMA)
        connection.execute(METRICS_SCHEMA)
        connection.execute(AUTH_SCHEMA)
        install_browsing(connection, postgres=True)
        connection.execute(
            "ALTER TABLE alert_status_history ADD COLUMN IF NOT EXISTS actor_id TEXT NOT NULL DEFAULT 'system'"
        )
        connection.execute(
            "ALTER TABLE alert_status_history ADD COLUMN IF NOT EXISTS actor_name TEXT NOT NULL DEFAULT 'Motor SOC'"
        )
